            .ToArray();

        var antworten = await Task.WhenAll(aufgaben);

        var erfolgreiche = antworten.Where(a => a.StatusCode == HttpStatusCode.Created).ToList();
        var abgelehnte = antworten.Where(a => a.StatusCode == HttpStatusCode.Conflict).ToList();

        Assert.Single(erfolgreiche);
        Assert.Equal(anzahlVersuche - 1, abgelehnte.Count);
        Assert.Equal(anzahlVersuche, erfolgreiche.Count + abgelehnte.Count); // keine unerwarteten Statuscodes (z. B. 500)

        foreach (var antwort in abgelehnte)
        {
            Assert.Equal("application/problem+json", antwort.Content.Headers.ContentType?.MediaType);
            var problemDetails = await antwort.Content.ReadFromJsonAsync<ProblemDetails>();
            Assert.Equal("sitzplatz_belegt", problemDetails!.Type);
        }

        await using var pruefContext = OeffnePruefContext();
        var belegungen = await pruefContext.Sitzplatzbelegungen
            .Where(s => s.VeranstaltungId == "E2" && s.SitzplatzCode == sitzplatzCode)
            .ToListAsync();
        Assert.Single(belegungen);
        Assert.Equal(1, await pruefContext.Buchungen.CountAsync());
    }
    ```
    **Warum Veranstaltung `E2` und nicht `E1`:** `E2` ist laut Anfangsdatenbestand (`anfangsdatenbestand.json`, Preiskategorien `E2-A`/`E2-B`) vollständig frei — kein bereits belegter Platz kann versehentlich mit `sitzplatzCode = "N9"` kollidieren oder das Ergebnis verfälschen. `E2-A` ist eine gültige `PreiskategorieId` dieser Veranstaltung (bereits in `BuchungenEndpointTests` als Präzedenzfall verwendet).
    **Warum `Assert.Equal(anzahlVersuche, erfolgreiche.Count + abgelehnte.Count)`:** Reine Absicherung, dass kein Versuch mit einem unerwarteten dritten Statuscode (z. B. `500` durch einen unbehandelten Fehler unter Last) durchrutscht, ohne dass der Test das bemerkt — schärfer als nur die beiden erwarteten Buckets zu zählen.
    **Warum ein separater `pruefContext` statt eines der 50 Request-Contexts:** Jeder der 50 Requests hat seinen eigenen, kurzlebigen `AppDbContext`, der nach Antwortversand disposed ist. Die Endzustandsprüfung (AC #2) braucht einen frischen, unabhängigen Context — exakt das bereits in `BuchungenServiceTests.cs` etablierte Prinzip ("frischer Request-Context"), hier nur außerhalb der Service-Schicht angewendet.

