    ```csharp
    using System.Net;
    using System.Net.Http.Json;
    using Microsoft.AspNetCore.Mvc;
    using Microsoft.AspNetCore.Mvc.Testing;
    using Microsoft.EntityFrameworkCore;
    using seed_a_backend.Api.Data;
    using seed_a_backend.Api.DTOs;
    using seed_a_backend.Tests.TestSupport;

    namespace seed_a_backend.Tests;

    public class NebenlaeufigkeitsTests : IAsyncLifetime
    {
        private WebApplicationFactory<Program> _factory = null!;
        private HttpClient _client = null!;

        public async ValueTask InitializeAsync()
        {
            var connectionString = SqlServerTestDatabase.BuildConnectionString(nameof(NebenlaeufigkeitsTests));

            var db = await SqlServerTestDatabase.CreateFreshContextAsync(nameof(NebenlaeufigkeitsTests));
            await db.DisposeAsync();

            _factory = new WebApplicationFactory<Program>().WithWebHostBuilder(builder =>
            {
                builder.UseSetting("ConnectionStrings:Default", connectionString);
            });
            _client = _factory.CreateClient();
        }

        public async ValueTask DisposeAsync()
        {
            _client.Dispose();
            await _factory.DisposeAsync();
            await SqlServerTestDatabase.DropAsync(nameof(NebenlaeufigkeitsTests));
        }

        private AppDbContext OeffnePruefContext() =>
            new(new DbContextOptionsBuilder<AppDbContext>()
                .UseSqlServer(SqlServerTestDatabase.BuildConnectionString(nameof(NebenlaeufigkeitsTests)))
                .Options);
    }
    ```
    **Warum eine eigene Testklasse statt Erweiterung von `BuchungenEndpointTests`:** xUnit v3 erzeugt standardmäßig pro `[Fact]` eine neue Instanz der Testklasse und ruft `InitializeAsync`/`DisposeAsync` davor/danach auf — jeder Test dieser Klasse bekommt dadurch automatisch eine frische, isolierte Datenbank (`EnsureDeletedAsync` + `MigrateAsync` in `CreateFreshContextAsync`). Eine eigene Klasse mit eigenem Discriminator hält diese Nebenläufigkeitstests unabhängig von den bereits existierenden funktionalen Tests in `BuchungenEndpointTests` (Story 2.6) und vermeidet, dass ein künftiger AC-Test dort versehentlich mit hoher paralleler Last kollidiert.
    **Warum echte HTTP-Requests über `WebApplicationFactory`/`HttpClient` statt direkter `BuchungenService`-Aufrufe (wie in `BuchungenServiceTests.cs`, Story 2.6):** Ein einzelner `AppDbContext` ist nicht threadsicher und wird in der Produktion pro HTTP-Request neu aus der DI-Scope erzeugt (`AddScoped<AppDbContext>`, EF-Core-Default). Nur der Weg über echte parallele HTTP-Requests gegen `WebApplicationFactory` erzeugt für jeden Versuch einen eigenen Scope mit eigenem `AppDbContext`/eigener SQL-Verbindung — echte Nebenläufigkeit auf DB-Ebene, exakt wie in Story 2.6 Dev Notes ("Warum Story 2.8 unverändert auf dieser Implementierung aufbaut") vorgesehen. Ein gemeinsam genutzter `AppDbContext` aus mehreren `Task`s heraus (wie es ein direkter Service-Aufruf bräuchte) würde die Nebenläufigkeit nicht real testen, sondern nur EF-Core-interne Race Conditions im Change Tracker provozieren.

